      font-size:13px;\n    }\n\t.table-mini{\n        font-size:11px;\n    }\n    </style>\n</style>\n";$krocdyqy="no";function cekstatuskantong($status,$stattempat,$sah,$statusrelease){$yhfhqrozgtk="status";$mrgixxjzesyn="resulstatus";$resulstatus="";$grgojcypx="stattempat";$vyjkxrobbu="resulstatus";$oxdglcoghz="resulstatus";$lgypocfr="resulstatus";$resulstatus="resulstatus";$gtgxqptlvest="resulstatus";$resulstatus="resulstatus";$cvqlifprgnd="stattempat";$stattempat="stattempat";switch(${$yhfhqrozgtk}){case"0":$resulstatus="Kosong";if($stattempat==NULL)$resulstatus="Kosong di logistik";if(${$grgojcypx}=="0")${$mrgixxjzesyn}="Kosong di Logistik";if(${$cvqlifprgnd}=="1")$resulstatus="Kosong di Aftap";break;case"1":if($sah=="1"){$jftgtfei="resulstatus";${$jftgtfei}="Karantina";}else{$resulstatus="resulstatus";$resulstatus="Belum disahkan";}break;case"2":switch($statusrelease){case"0":$resulstatus="Sehat, belum release";break;case"1":$resulstatus="Sehat, Lulus";break;case"2":$resulstatus="Sehat, Tidak Lulus";break;case"3":$resulstatus="Sehat, Lulus (Catatan)";break;default:$resulstatus="Sehat, belum release";break;}break;case"3":${$oxdglcoghz}="Keluar";break;case"4":${$gtgxqptlvest}="Rusak";break;case"5":${$vyjkxrobbu}="Rusak-Gagal";break;case"6":$resulstatus="Dimusnahkan";break;case"7":${$lgypocfr}="Reaktif";break;case"8":$resulstatus="Uji Mutu (QC)";break;default:$resulstatus="Musnah";}return$resulstatus;}$namauser="namauser";function statuskantongserahterima($dst_statusktg,$dst_sahktg){$pohfivs="dst_statusktg";$ywcupphcgkdf="resulstatus";$dst_sahktg="dst_sahktg";$zopaaktorcv="resulstatus";$resulstatus="resulstatus";$resulstatus="";$resulstatus="resulstatus";switch(${$pohfivs}){case"0":${$ywcupphcgkdf}="Kosong";break;case"1":if($dst_sahktg=="1"){$resulstatus="resulstatus";$resulstatus="Karantina";}else{$negjofhid="resulstatus";${$negjofhid}="Aftap";}break;case"2":$resulstatus="Sehat";break;break;case"3":$resulstatus="Keluar";break;case"4":$resulstatus="Rusak";break;case"5":$resulstatus="Rusak-Gagal";break;case"6":${$zopaaktorcv}="Dimusnahkan";break;case"7":$resulstatus="Reaktif";break;default:$resulstatus="Tidak ada";}return$resulstatus;}$output="output";function serahterima($nokantong,$modul){$nokantongserahterima="nokantongserahterima";$fcaylwd="nokantongserahterima";$tfffnlcmn="fjudul";$vxzfehnsty="modul";$fjudul="fjudul";$vqhjurk="fjudul";global$dbi;$okviuytvh="nokantong";$bgmuov="nokantongserahterima";$gpgcpllfvp="fjudul";$dbi="dbi";$oiutcfynsqm="fjudul";$dtvesfhmvr="nokantongserahterima";$fhasil="";${$tfffnlcmn}="Judul Serah terima";$fno_kantonga=substr_replace($nokantong,"A",-1,1);$xjmehpd="nokantong";switch(${$vxzfehnsty}){case"Kantong Darah Aftap":${$gpgcpllfvp}="Serah terima kantong darah dari Pengambilan ke Pengolahan";$nokantongserahterima=$fno_kantonga;break;case"Sampel Pengujian":$fjudul="Serah terima sampel darah dari Pengambilan ke Pengujian/IMLTD";${$fcaylwd}=$fno_kantonga;break;case"Kantong Darah Pengolahan":$fjudul="Serah terima produk darah dari Pengolahan ke Pelulusan (Prolis)";${$dtvesfhmvr}=${$okviuytvh};break;case"Kantong Darah Pelulusan Produk":${$oiutcfynsqm}="Serah terima produk darah dari Pelulusan ke Penyimpanan/Distribusi";$nokantongserahterima=${$xjmehpd};break;case"Kantong Darah Uji Mutu":${$vqhjurk}="Serah terima produk darah dari Penyimpanan ke Uji Mutu (QC)";${$bgmuov}=$nokantong;break;}$fsqlsr="SELECT h.hst_id, h.hst_notrans, h.hst_bagpengirim, h.hst_bagpenerima, h.hst_tgl, h.hst_asal, h.hst_jenis_st, h.hst_user, h.hst_pengirim, h.hst_penerima, h.hst_penerima2, \n            h.hst_kode_alat, h.hst_termometer, h.hst_suhuterima, h.hst_kondisiumum, h.hst_peruntukan, h.hst_modul, h.hst_shift_pengirim, h.hst_shift_penerima, \n            d.dst_iddetail, d.dst_no_aftap, d.dst_tglaftap, d.dst_notrans, d.dst_nokantong, d.dst_statusktg, d.st_statusktg_new, d.dst_old_position, d.dst_new_position, \n            d.dst_sahktg, d.dst_sahktg_new, d.dst_merk, d.dst_golda, d.dst_rh, d.dst_kodedonor, d.dst_berat, d.dst_volumektg, d.dst_jenisktg, \n            d.dst_sah, d.dst_dsdp, d.dst_lamabaru, d.dst_donasi, d.dst_umur, d.dst_lama_aftap, d.dst_statuspengambilan, d.dst_kel, \n            d.dst_ptgaftap, d.dst_volambil, \n            CASE WHEN d.dst_samplevol='0' THEN 'Tidak Sesuai' ELSE 'Sesuai' END AS dst_samplevol, \n            CASE WHEN d.dst_sample='1' THEN 'Tidak' ELSE 'Ya' END AS `dst_sample`,\n            d.dst_samplejml, d.dst_tglolah, d.dst_tgled, d.dst_tglrelease, d.dts_hasilrelease, \n             d.dst_produk, d.dst_suhusimpan, \n            CASE WHEN d.`dst_imltd`='0' THEN 'Belum' WHEN d.`dst_imltd`='1' THEN 'Non Reaktif' WHEN d.`dst_imltd`='2' THEN 'Reaktif' END AS `dst_imltd`,\n            CASE WHEN d.`dst_kgd`='0' THEN 'Belum' WHEN d.`dst_kgd`='1' THEN 'Cocok' WHEN d.`dst_kgd`='2' THEN 'Tdk Cocok' END AS `dst_kgd`,\n            case when d.dst_reposisijarum='0' THEN 'Tidak' ELSE 'Ya' END AS `dst_reposisijarum`,\n             d.dst_caraambil, d.dst_oninsert\n            FROM serahterima AS h INNER JOIN serahterima_detail AS d ON h.hst_notrans = d.dst_notrans\n            WHERE d.dst_nokantong = '$nokantongserahterima' AND h.hst_jenis_st = '$modul'";$pojmbbhra="fhasil";$fceksr=mysqli_query($dbi,$fsqlsr);if(mysqli_num_rows($fceksr)>0){$infokeberterimaan="infokeberterimaan";$frslt_sr="frslt_sr";$mqoitn="frslt_sr";$frslt_sr="frslt_sr";$frslt_sr="frslt_sr";$fhasil="fhasil";$frslt_sr="frslt_sr";$frslt_sr="frslt_sr";$frslt_sr="frslt_sr";$frslt_sr="frslt_sr";$hvknyzhdqu="frslt_sr";$frslt_sr="frslt_sr";$frslt_sr="frslt_sr";$ciirygtv="frslt_sr";$infokeberterimaan="infokeberterimaan";$infokeberterimaan="infokeberterimaan";$infokeberterimaan="";$vichgorok="frslt_sr";$frslt_sr="frslt_sr";$infokeberterimaan="infokeberterimaan";$frslt_sr=mysqli_fetch_assoc($fceksr);switch($modul){case"Kantong Darah Aftap":$infokeberterimaan="\n                <tr><td>Asal Darah</td>         <td class=\"w3-hover-theme\">".$frslt_sr["hst_asal"]."</td></tr>\n                <tr><td>Lama 